from __future__ import annotations

import pytest

from risk import vol_pipeline
from risk.types import VolSeries


@pytest.fixture
def on_fake(monkeypatch, contract_fake):
    monkeypatch.setattr(vol_pipeline, "load_prices", contract_fake("mdata.load_prices").load_prices)


@pytest.mark.usefixtures("on_fake")
def test_pl02_runs_end_to_end(contract_sample):
    prices = contract_sample("mdata.Prices")
    vol = vol_pipeline.vol_series("ignored.csv", window=2)
    assert isinstance(vol, VolSeries)
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns.tickers == ("AAPL", "MSFT")
    assert vol.returns.dates == tuple(prices["dates"][1:])
    assert all(len(vol.values[ticker]) == len(prices["dates"]) - 1 for ticker in vol.returns.tickers)
    assert all(vol.values[ticker][:2] == (None, None) for ticker in vol.returns.tickers)


@pytest.mark.usefixtures("on_fake")
def test_pl02_narrows_to_tickers():
    vol = vol_pipeline.vol_series("ignored.csv", window=2, tickers=["MSFT"])
    assert set(vol.values) == {"MSFT"}


@pytest.mark.usefixtures("on_fake")
def test_pl02_rejects_a_window_below_two():
    with pytest.raises(ValueError, match="window"):
        vol_pipeline.vol_series("ignored.csv", window=1)

